MATCH (fa:FlightAccident {name: "Pegasus Airlines Flight 2193"})-[:involves]->(am:AircraftModel)
RETURN DISTINCT am.name AS name,
       COALESCE(am.service_entry, 'Unknown') AS serviceEntry;

MATCH (m:AircraftManufacturer)
WHERE m.name = "Ulan-Ude Aviation Plant"
RETURN m.country AS country;

MATCH (f:FlightAccident)-[:involves]->(a:AircraftModel)-[:manufacturedBy]->(m:AircraftManufacturer)
WHERE m.name = "Fiat Aviazione"
RETURN f.name AS accidentName, f.date AS accidentDate;

MATCH (fa:FlightAccident)-[:destinedFor]->(dest:Airport {name: "Dalian Zhoushuizi International Airport"}),
      (fa)-[:departsFrom]->(dep:Airport)
RETURN DISTINCT dep.name AS departingAirportName;

MATCH (acc:FlightAccident)
WHERE EXISTS{ MATCH (acc)-[:departsFrom]->(ap:Airport) WHERE ap.name = 'Stockholm Arlanda Airport' }
   OR EXISTS{ MATCH (acc)-[:involves]->(md:AircraftModel) WHERE md.name = 'McDonnell Douglas MD-81' }
RETURN count(acc) AS totalAccidents;

MATCH (fa:FlightAccident)-[:departsFrom]->(ap:Airport)
WHERE fa.flight_number CONTAINS 'Sriwijaya Air' OR fa.flight_number CONTAINS 'Adam Air'
RETURN DISTINCT ap.name AS AirportName;

MATCH (fa:FlightAccident)-[:operatedBy]->(op:Operator)
WHERE fa.name CONTAINS 'American Airlines Flight 383'
RETURN DISTINCT op.name AS Operator;

MATCH (fa:FlightAccident)-[:destinedFor|departsFrom]->(a:Airport)
WHERE a.iata_code = "RUT" OR a.name CONTAINS "Mojave" OR a.name CONTAINS "Rutan"
RETURN DISTINCT fa.name AS accidentName;

MATCH (am:AircraftModel)
WHERE (
  (am)-[:manufacturedBy]->(:AircraftManufacturer {name: "LET Aircraft Industries"})
) OR (
  (am)-[:involves]->(:FlightAccident {name: "Parachute Kemerovo Let L-410UVP-E"})
)
RETURN DISTINCT am.name AS model_name;
